<?php

// PHP-CS-Fixer formats the PHP code, like Prettier formats the TypeScript code.
// Check: `pnpm nx run api:format-check`. Fix: `pnpm nx run api:format`.
// https://cs.symfony.com/doc/config.html

$finder = (new PhpCsFixer\Finder())
    ->in(__DIR__)
    ->exclude('var')
    ->notPath([
        // Generated by Symfony and Symfony Flex, not written by us.
        'config/bundles.php',
        'config/reference.php',
    ])
;

return (new PhpCsFixer\Config())
    ->setRules([
        // The coding standard of Symfony: https://symfony.com/doc/current/contributing/code/standards.html
        '@Symfony' => true,
        // The @Symfony set turns `/** @var Type $x */` above a `return` into a plain comment,
        // and PHPStan reads types only from `/** */` comments.
        'phpdoc_to_comment' => ['ignored_tags' => ['var']],
    ])
    ->setFinder($finder)
;
